// Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
// decrypt <client_home> <ct_out_dir> <results_csv>
// Client: decrypt logits, apply the reference's exact decision rule
// (logit >= ln(0.64/0.36)).
#include "common.hpp"
#include <iostream>
#include <iomanip>

int main(int argc, char** argv) try {
    if (helpRequested(argc, argv)) {
        std::cout << "usage: decrypt <client_home> <ct_out_dir> <results_csv>\n\nStage 4 of 4 (client). Decrypts the logit ciphertexts in <ct_out_dir> and\nwrites one logit and decision per record to <results_csv>.\n";
        return 0;
    }
    std::string home = argc > 1 ? argv[1] : "client_home";
    std::string in   = argc > 2 ? argv[2] : home + "/ct_out";
    std::string outc = argc > 3 ? argv[3] : home + "/results.csv";

    CryptoContext<DCRTPoly> cc;  mustDeserialize(cc, home + "/context.bin");
    cc->Enable(PKE); cc->Enable(KEYSWITCH); cc->Enable(LEVELEDSHE); cc->Enable(ADVANCEDSHE);
    PrivateKey<DCRTPoly> sk;     mustDeserialize(sk, home + "/key_secret.bin");

    std::ifstream meta(home + "/client_meta.txt");
    if (!meta) throw std::runtime_error("Cannot open " + home + "/client_meta.txt");
    int F; meta >> F;
    std::vector<double> skip(2 * F);
    for (auto& v : skip) meta >> v;
    double TH; meta >> TH;

    const std::string mpath = home + "/ct_in/manifest.txt";
    std::ifstream manifest(mpath);
    if (!manifest) throw std::runtime_error("Cannot open " + mpath);
    int F2 = 0; size_t nBatches = 0;
    manifest >> F2 >> nBatches;
    if (!manifest || F2 != F) throw std::runtime_error("Malformed " + mpath);

    std::ofstream csv(outc);
    csv << std::setprecision(10);
    csv << "logit,decision\n";
    size_t total = 0;
    for (size_t b = 0; b < nBatches; ++b) {
        size_t nRec = 0;
        if (!(manifest >> nRec)) throw std::runtime_error("Malformed " + mpath);
        Ciphertext<DCRTPoly> ct;
        mustDeserialize(ct, in + "/ct_logit_b" + std::to_string(b) + ".bin");
        Plaintext pt;
        cc->Decrypt(sk, ct, &pt);          // batched decode: all-or-nothing
        pt->SetLength(nRec);
        auto vals = pt->GetRealPackedValue();
        for (size_t i = 0; i < nRec; ++i)
            csv << vals[i] << "," << (vals[i] >= TH ? 1 : 0) << "\n";
        total += nRec;
    }
    std::cout << "decrypt: " << total << " results -> " << outc << "\n";
    return 0;
} catch (const std::exception& e) {
    std::cerr << "decrypt: error: " << e.what() << "\n";
    return 1;
}
